export const sensorTags={i0:'a0 / I0.0',i1:'a1 / I0.1',i2:'b0 / I0.2',i3:'b1 / I0.3'};
export function configureHMI(s,recipe){if(s.run)return {ok:false,message:'Pulsa Paro antes de aplicar ajustes.'};if(s.fault)return {ok:false,message:'Resuelve y rearma la alarma antes de ajustar.'};const target=Number(recipe.target),delays=Object.fromEntries(['AP','BP','BM','AM'].map(k=>[k,Number(recipe.delays[k])]));if(!Number.isInteger(target)||target<1||target>50||Object.values(delays).some(v=>!Number.isFinite(v)||v<0||v>5))return {ok:false,message:'Ciclos: entero de 1 a 50. Esperas: de 0 a 5 segundos.'};if(target!==s.target&&s.cycles!==0)return {ok:false,message:'Reinicia C1 antes de cambiar el objetivo del lote.'};s.target=target;s.delays=delays;s.timers={};s.scan=null;return {ok:true,message:'Ajustes escritos en el PLC. Pulsa Marcha para iniciar.'};}
export function sensorAlarm(s,stage){const key=({AP:'i1',BP:'i3',BM:'i2',AM:'i0'})[stage];if(!key)return;const alarm={code:'S'+({i0:'01',i1:'02',i2:'03',i3:'04'})[key],sensor:key,tag:sensorTags[key],time:s.time,active:true,ack:false,message:'Tiempo excedido esperando '+sensorTags[key]};s.alarms.unshift(alarm);s.alarms.length=Math.min(10,s.alarms.length);}
export function acknowledgeAlarms(s){for(const a of s.alarms)a.ack=true;}
